const fs = require('fs');
const path = require('path');
function walkSync(dir, fileList) {
    const files = fs.readdirSync(dir);

    fileList = fileList || [];

    files.forEach(function (file) {
        if (fs.statSync(dir + file).isDirectory()) {
            fileList = walkSync(dir + file + '/', fileList);
        } else if (file.indexOf('.d.ts') === -1 && file.indexOf('.map') === -1) {
            fileList.push(file);
        }
    });
    return fileList;
}

function getStepDefinitionFiles(folders) {
    return folders
        .map(dir => {
            const files = walkSync(dir).map(file => path.resolve(dir + file));
            return files;
        })
        .reduce((a, b) => a.concat(b), []);
}
module.exports.walkSync = walkSync;
module.exports.getStepDefinitionFiles = getStepDefinitionFiles;
